using System;using System.IO;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using SolidWorks.Interop.sldworks;
public static class DirectionProbe {
 static Dictionary<string,object> O(params object[] p){var r=new Dictionary<string,object>();for(int i=0;i<p.Length;i+=2)r[(string)p[i]]=p[i+1];return r;}
 public static void Run(string root){var sw=(ISldWorks)Marshal.GetActiveObject("SldWorks.Application");var ser=new JavaScriptSerializer();ser.MaxJsonLength=int.MaxValue;var inp=(Dictionary<string,object>)ser.DeserializeObject(File.ReadAllText(Path.Combine(root,"inputs","assembly_original.json")));var all=new List<object>();foreach(string path in new[]{(string)inp["source"],Path.Combine(root,"models","FullGripper.SLDASM")}){var d=(IModelDoc2)sw.GetOpenDocumentByName(path);for(var gf=(IFeature)d.FirstFeature();gf!=null;gf=(IFeature)gf.GetNextFeature())if(gf.GetTypeName2()=="MateGroup"){for(var f=(IFeature)gf.GetFirstSubFeature();f!=null;f=(IFeature)f.GetNextSubFeature()){var m=f.GetSpecificFeature2() as IMate2;if(m==null)continue;var es=new List<object>();for(int i=0;i<2;i++){var me=(IMateEntity2)m.MateEntity(i);var c=(IComponent2)me.ReferenceComponent;var face=me.Reference as IFace2;var surf=face==null?null:(ISurface)face.GetSurface();es.Add(O("component",c.Name2,"entity_params",me.EntityParams,"surface_params",surf==null?null:surf.IsPlane()?surf.PlaneParams:surf.IsCylinder()?surf.CylinderParams:null,"face_normal",face==null?null:face.Normal,"sense",face==null?false:face.FaceInSurfaceSense(),"transform",c.Transform2.ArrayData));}all.Add(O("file",path,"mate",f.Name,"type",m.Type,"align",m.Alignment,"entities",es));}}}File.WriteAllText(Path.Combine(root,"checks","direction_probe.json"),ser.Serialize(all));Console.WriteLine("Direction probes "+all.Count);}
}
